import React, { useState } from 'react';

function HelpSupport() {
  const [submitted, setSubmitted] = useState(false);
  const [ticketText, setTicketText] = useState('');

  function handleSubmit(e) {
    e.preventDefault();
    if (!ticketText.trim()) return;
    setSubmitted(true);
    setTicketText('');
  }

  return (
    <section className="panel" style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
      <div className="panel-heading">
        <h2>❓ Help & Support</h2>
        <p>Frequently asked questions & workspace support desk</p>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
        <div className="panel" style={{ background: 'var(--bg-cream)' }}>
          <h3>Frequently Asked Questions</h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '14px', marginTop: '14px' }}>
            <details style={{ background: '#fff', padding: '12px 16px', borderRadius: '8px', border: '1px solid var(--soft-border)' }}>
              <summary style={{ fontWeight: '700', cursor: 'pointer' }}>How do Admin task assignments work?</summary>
              <p style={{ marginTop: '8px', fontSize: '0.88rem', color: 'var(--text-muted)' }}>
                Admins select registered users from the assignee dropdown when creating a task. The assigned user receives an in-app toast notification alert immediately.
              </p>
            </details>
            <details style={{ background: '#fff', padding: '12px 16px', borderRadius: '8px', border: '1px solid var(--soft-border)' }}>
              <summary style={{ fontWeight: '700', cursor: 'pointer' }}>How do Users update task status?</summary>
              <p style={{ marginTop: '8px', fontSize: '0.88rem', color: 'var(--text-muted)' }}>
                Users navigate to the Tasks tab, locate their assigned task, and use the inline status dropdown to change status between Pending, In Progress, and Completed.
              </p>
            </details>
            <details style={{ background: '#fff', padding: '12px 16px', borderRadius: '8px', border: '1px solid var(--soft-border)' }}>
              <summary style={{ fontWeight: '700', cursor: 'pointer' }}>Can Users leave comments on tasks?</summary>
              <p style={{ marginTop: '8px', fontSize: '0.88rem', color: 'var(--text-muted)' }}>
                Yes! Click the 💬 Comments button on any task item to communicate back and forth with the Admin.
              </p>
            </details>
          </div>
        </div>

        <div className="panel" style={{ background: 'var(--bg-cream)' }}>
          <h3>Contact Workspace Support</h3>
          {submitted ? (
            <div style={{ background: '#eaf6f0', color: '#22543d', padding: '16px', borderRadius: '8px', marginTop: '14px' }}>
              ✅ Support request submitted! Our team will respond to your registered email shortly.
            </div>
          ) : (
            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '12px', marginTop: '14px' }}>
              <label style={{ fontSize: '0.85rem', fontWeight: '600' }}>Message / Issue Description</label>
              <textarea
                rows="4"
                value={ticketText}
                onChange={(e) => setTicketText(e.target.value)}
                placeholder="Describe your question or issue..."
                style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid var(--soft-border)' }}
                required
              />
              <button type="submit" className="btn-primary" style={{ padding: '10px 16px', alignSelf: 'flex-start' }}>
                Submit Support Ticket
              </button>
            </form>
          )}
        </div>
      </div>
    </section>
  );
}

export default HelpSupport;
